import csv,re,sys,os
S='/Users/tj/lunenburgbudgets/sources/'
OUT='/private/tmp/claude-501/-Users-tj-lunenburgbudgets/26fe2632-277f-4dfc-9721-fd6ae3bfacb8/scratchpad/track/early.csv'
cols="cycle_fy,date,body,kind,what_happened,amount,requester,rank,vote,doc,text,page_or_line,quote,note".split(',')
def norm(s): return re.sub(r'\s+',' ',s.replace('’',"'").replace('“','"').replace('”','"')).strip()
def locate(text,quote):
    p=S+text
    raw=open(p,encoding='utf-8',errors='replace').read().split('\n')
    # build normalized stream with line map
    stream='';idx=[]
    for i,l in enumerate(raw):
        n=norm(l)
        if not n: continue
        start=len(stream); stream+=n+' '; idx.append((start,i+1))
    q=norm(quote)
    pos=stream.find(q)
    if pos<0: raise SystemExit('QUOTE NOT FOUND in %s: %s'%(text,quote[:80]))
    ln=[l for s,l in idx if s<=pos][-1]
    page=None
    for i in range(ln-1,-1,-1):
        m=re.match(r'===PAGE (\d+)===',raw[i])
        if m: page=m.group(1);break
    return ln,page
R=[]
def row(cy,date,body,kind,what,amount,req,rank,vote,doc,text,quote,note='',loc=None):
    if text and quote and not quote.startswith('['):
        ln,pg=locate(text,quote)
        l=('pdf p%s, '%pg if pg else '')+'text line %d'%ln
        if loc: l=loc+' ('+l+')'
    else: l=loc or ''
    R.append(dict(cycle_fy=cy,date=date,body=body,kind=kind,what_happened=what,amount=amount,requester=req,rank=rank,vote=vote,doc=doc,text=text,page_or_line=l,quote=quote,note=note))
def M(board,name): return ('meetings/%s/%s.pdf'%(board,name),'meetings/text/%s/%s.txt'%(board,name))
def AR(n,fy): return ('town-annual-reports/docs/%s-fy-%s-annual-town-report.pdf'%(n,fy),'town-annual-reports/text/%s-fy-%s-annual-town-report.txt'%(n,fy))

